    author_books = self._repos['AuthorRepository'].read_all_authors()
    author_id_to_name = {author.id: author.name for author in author_books}

    for book in books:
        if book.title and query.lower() in book.title.lower():
            results.append(book)
        elif book.author_id is not None and book.author_id in author_id_to_name:
            author_name = author_id_to_name[book.author_id]
            if query.lower() in author_name.lower():
                results.append(book)
